    /// List a team's artifacts
    ///
    /// Returns all artifacts owned by the specified team. Artifacts represent
    /// AI-generated or user-uploaded files associated with agent sessions,
    /// threads, or sandboxes such as images, documents, and code outputs.
    /// The authenticated user must be a member of the team. Attempting to list
    /// artifacts for a team the caller does not have access to returns 404
    /// rather than 403 to avoid leaking team existence.
    /// Results are returned in a single page without cursor pagination. Each
    /// artifact in the response reflects the state of its current version,
    /// including a short-lived signed `file_url` for direct download.
    ///
    /// - Parameters:
    ///   - team: Team ID (`tea_...`). The authenticated user must be a member of this team.
    ///   - groupKey: Case-sensitive exact group key. Mutually exclusive with group_key_prefix; null keys do not match.
    ///   - groupKeyPrefix: Nonempty case-sensitive literal prefix (percent, underscore and backslash are literal). Mutually exclusive with group_key.
    /// - Returns: Successful response
    public func artifacts(team: String, groupKey: String? = nil, groupKeyPrefix: String? = nil) async throws -> TeamArtifactsResponse {
        var query: [(String, String)] = []
        if let groupKey = groupKey {
            query.append(("group_key", groupKey))
        }
        if let groupKeyPrefix = groupKeyPrefix {
            query.append(("group_key_prefix", groupKeyPrefix))
        }
        return try await http.request("/api/v1/teams/\(team)/artifacts", query: query)
    }

    /// Preview Team deletion impact
    ///
    /// Returns the number of stored custom-object rows that deleting this Team will
    /// physically delete. The count includes rows hidden after ordinary soft
    /// deletion. This read-only preview does not delete or restore data.
    ///
    /// - Parameters:
    ///   - team: Team ID (`team_...`) to inspect.
    /// - Returns: Stored custom-object rows and the existing physical-deletion contract.
    public func dependents(team: String) async throws -> TeamDeleteImpactResponse {
        return try await http.request("/api/v1/teams/\(team)/dependents")
    }

    /// Create a team invite (server-to-server)
    ///
    /// Generates a new invite code for the specified team using server-to-server
    /// authentication. Unlike the user-facing create endpoint, this variant does not
    /// require the caller to be a team member it is intended for privileged
    /// back-end services acting on behalf of your platform.
    /// The returned code is a short alphanumeric string that users can present to
    /// join the team. Each call produces a new code; previously issued codes are
    /// not invalidated by this request.
    ///
    /// - Parameters:
    ///   - team: Team ID (`tm_...`) identifying the team for which to generate the invite code.
    /// - Returns: Successful response
    public func invites(team: String) async throws -> TeamInvitesResponse {
        return try await http.request("/api/v1/teams/\(team)/invites", method: "POST")
    }

    /// Join a team
    ///
    /// Adds a principal to a team that is visible to the authenticated user.
    /// By default, the currently authenticated user joins the team. Provide `agent`
    /// to add an agent to the team instead the caller must already be a member of
    /// the team to do so. Provide `user` (by ID) or `email` to add another user from
    /// your organization the caller must be a team owner, team admin, or org admin.
    /// Only one of `agent`, `user`, or `email` may be supplied per request.
    /// If the target principal is already a member of the team, the request succeeds
    /// without creating a duplicate membership. Server-to-server callers are not
    /// permitted to use this endpoint; use the invite-code endpoint instead.
    ///
    /// - Parameters:
    ///   - team: Team ID (`team_...`) to join.
    ///   - input: Request body.
    /// - Returns: Empty response the principal is now a member of the team.
    public func join(team: String, input: TeamJoinInput) async throws {
        try await http.requestVoid("/api/v1/teams/\(team)/join", method: "POST", body: input)
    }

    /// Leave a team
    ///
    /// Removes a principal from a team. By default, the authenticated user removes
    /// themselves from the team. Provide `agent` to remove an agent instead the
    /// caller must be a member of the team to do so.
    /// Team owners cannot leave their own team. To transfer ownership first, use
    /// the update-membership endpoint, then call this endpoint.
    /// For server-to-server requests, `user` is required to identify which user
    /// should be removed.
    ///
    /// - Parameters:
    ///   - team: Team ID (`team_...`) to leave.
    /// - Returns: Empty response the principal has been removed from the team.
    public func leave(team: String) async throws {
        try await http.requestVoid("/api/v1/teams/\(team)/leave", method: "DELETE")
    }

    /// List task assignees for a team
    ///
    /// Returns the list of principals users and agents that can be assigned
    /// to tasks within the team. Results include both human members and AI agents
    /// and are sorted alphabetically by display name.
    /// This endpoint is only available for team-scoped contexts. Calling it with a
    /// user-scoped owner returns a 400 error. The authenticated user must be a
    /// member of the team or hold org-admin access. App-scoped developer and
    /// server-to-server callers may list assignees for teams in their app so they
    /// can select the explicit user or agent actor required by privileged task
    /// mutations.
    ///
    /// - Parameters:
    ///   - team: Team ID (`tem_...`).
    ///   - org: Explicit organization (`org_...`) for developer and server-to-server calls. Pass null for a team outside an organization.
    /// - Returns: Successful response
    public func taskAssignees(team: String, org: String? = nil) async throws -> TeamTaskAssigneesResponse {
        var query: [(String, String)] = []
        if let org = org {
            query.append(("org", org))
        }
        return try await http.request("/api/v1/teams/\(team)/task_assignees", query: query)
    }
}
